    path: ".github/workflows/build-apk.yml",
    language: "properties",
    description: "Quy trình GitHub Actions tự động build APK với Gradle 8.7 và JDK 17",
    content: "name: Build Android APK\n\non:\n  push:\n    branches: [ main, master, '**' ]\n    tags:\n      - 'v*'\n  pull_request:\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  build:\n    name: Build Debug APK\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout Code\n        uses: actions/checkout@v4\n\n      - name: Set up JDK 17\n        uses: actions/setup-java@v4\n        with:\n          java-version: '17'\n          distribution: 'temurin'\n\n      - name: Setup Gradle 8.7\n        uses: gradle/actions/setup-gradle@v4\n        with:\n          gradle-version: '8.7'\n          cache-read-only: false\n\n      - name: Make Gradlew Executable\n        run: |\n          if [ -f android/gradlew ]; then\n            chmod +x android/gradlew\n          fi\n\n      - name: Build Debug APK with Gradle\n        run: |\n          cd android\n          if [ -f ./gradlew ]; then\n            ./gradlew assembleDebug --no-daemon --stacktrace\n          else\n            gradle assembleDebug --no-daemon --stacktrace\n          fi\n\n      - name: Locate Generated APK\n        id: find_apk\n        run: |\n          APK_PATH=$(find android/app/build/outputs/apk/debug -name \"*.apk\" | head -n 1)\n          if [ -z \"$APK_PATH\" ]; then\n            echo \"Error: APK not found!\"\n            exit 1\n          fi\n          echo \"Found APK: $APK_PATH\"\n          echo \"apk_path=$APK_PATH\" >> $GITHUB_OUTPUT\n\n      - name: Upload Debug APK Artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: DroidTranslator-Debug-APK\n          path: ${{ steps.find_apk.outputs.apk_path }}\n          retention-days: 30\n\n      - name: Create GitHub Release\n        if: startsWith(github.ref, 'refs/tags/v')\n        uses: softprops/action-gh-release@v2\n        with:\n          files: ${{ steps.find_apk.outputs.apk_path }}\n          name: Release ${{ github.ref_name }}\n          generate_release_notes: true\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n"
